-- READ-ONLY schema drift check (generated by hand-run node snippet, 2026-11-20).
-- Paste into the Supabase SQL editor. For each numbered script it checks one object that
-- script creates. "missing" = that script (probably) hasn't been run on this database.
-- Changes nothing.
SELECT script, kind, object,
  CASE kind
    WHEN 'table'    THEN CASE WHEN to_regclass('public.' || object) IS NOT NULL THEN 'ok' ELSE 'MISSING' END
    WHEN 'function' THEN CASE WHEN EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
                                           WHERE n.nspname = 'public' AND p.proname = object) THEN 'ok' ELSE 'MISSING' END
    WHEN 'column'   THEN CASE WHEN EXISTS (SELECT 1 FROM information_schema.columns
                                           WHERE table_schema = 'public' AND table_name = split_part(object, '.', 1)
                                             AND column_name = split_part(object, '.', 2)) THEN 'ok' ELSE 'MISSING' END
    ELSE 'n/a (check manually)'
  END AS status
FROM (VALUES
